<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref } from 'vue'
import MetricChart from './components/MetricChart.vue'
import { fmtBytes, fmtTime, post, request, token } from './api'

type User = { id:number,userName:string,displayName:string,role:string }
const currentUser = ref<User|null>(null), login = reactive({ userName:'admin', password:'ChangeMe!123' })
const busy = ref(false), notice = ref(''), error = ref(''), view = ref('dashboard'), resources = ref<any>({directories:[],services:[]})
const menu = [
  ['dashboard','◫','运行概览'], ['files','⌗','文件发布'], ['logs','≡','日志查看'], ['services','◉','服务管理'],
  ['processes','⌁','进程管理'], ['configs','⌘','配置文件'], ['audit','◇','审计记录'], ['users','⊕','用户管理'], ['settings','⚙','资源设置']
]
const title = computed(() => menu.find(x => x[0] === view.value)?.[2] || '')
const visibleMenu = computed(() => menu.filter(x => !['audit','users','settings'].includes(x[0]) || currentUser.value?.role === 'Admin'))
const configRoots = computed(() => resources.value.directories.filter((x:any)=>x.canUpload))
const filteredProcesses = computed(() => {const q=processFilter.value.trim().toLowerCase();return q?processes.value.filter((p:any)=>String(p.pid).includes(q)||String(p.name).toLowerCase().includes(q)):processes.value})
const dashboard = ref<any>({ metrics:[],services:[] }), files = ref<any>({items:[]}), deployments = ref<any[]>([]), services = ref<any[]>([]), processes = ref<any[]>([]), audits = ref<any[]>([]), users = ref<any[]>([]), results = ref<any[]>([]), journal = ref<any[]>([])
const currentRoot = ref(''), currentPath = ref(''), selectedFile = ref<File|null>(null)
const deleteTarget = ref<any|null>(null)
const replaceTarget = ref<any|null>(null), replacementFile = ref<File|null>(null)
const logForm = reactive({ rootId:'', path:'', start:localDate(-1), end:localDate(0), query:'', regex:false, caseSensitive:false, limit:1000 })
const journalForm = reactive({ service:'', start:localDate(-1), end:localDate(0), query:'', priority:'', limit:1000 })
const configEdit = reactive({ rootId:'', path:'', content:'', version:'' }), configFiles = ref<string[]>([]), processFilter = ref('')
const directoryForm = reactive({ id:'', name:'', path:'', canUpload:false, relatedService:'', backupExcludes:'' }), serviceName = ref('')
const serviceCreateMode = ref<'existing'|'package'>('existing')
const serviceModal = ref(false)
const servicePublishForm = reactive({ serviceName:'', runDirectory:'', mainProgram:'', backupExcludes:'logs;files;download' })
const servicePackage = ref<File|null>(null)
const logSourceForm = reactive({ id:'', name:'', path:'', filePattern:'*.log;*.txt' })
const userModal = ref(''), selectedUser = ref<any>(null), userEdit = reactive({ displayName:'', role:'Viewer', isEnabled:true })
const logContext = ref<any|null>(null)
const logQueryOpen = ref(true)
const journalQueryOpen = ref(true)
const logTab = ref<'files'|'journal'>('files')
let timer:number|undefined, journalAbort:AbortController|undefined
const following = ref(false)
const journalElement = ref<HTMLElement|null>(null)

function localDate(hours:number) { const d = new Date(Date.now()+hours*3600000); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,16) }
function flash(message:string) { notice.value=message; setTimeout(()=>notice.value='',3000) }
async function execute(fn:()=>Promise<void>) { busy.value=true; error.value=''; try { await fn() } catch(e:any){ error.value=e.message } finally { busy.value=false } }
async function signIn(){ await execute(async()=>{ const r=await post('/auth/login',login); token.set(r.token); currentUser.value=r.user; await boot() }) }
function signOut(){ token.clear(); currentUser.value=null; if(timer) clearInterval(timer) }
async function boot(){ currentUser.value=await request('/auth/me'); resources.value=await request('/resources'); currentRoot.value ||= resources.value.directories[0]?.id || ''; logForm.rootId ||= resources.value.logs?.[0]?.id || ''; journalForm.service ||= resources.value.services[0] || ''; await load('dashboard'); timer=window.setInterval(()=>{ if(view.value==='dashboard') refreshMetrics() },1000) }
async function load(next:string){ if(next!=='logs'&&following.value){journalAbort?.abort();following.value=false} view.value=next; await execute(async()=>{ if(next==='dashboard') await refreshDashboard(); if(next==='files') await loadFiles(); if(next==='services') services.value=await request('/services'); if(next==='processes') processes.value=await request('/processes'); if(next==='configs') await openConfigPage(); if(next==='audit') audits.value=await request('/audit'); if(next==='users') users.value=await request('/users') }) }
async function refreshDashboard(){ dashboard.value=await request('/dashboard') }
async function refreshMetrics(){ try { dashboard.value.metrics=await request('/metrics') } catch { /* 全局操作仍可继续，下一秒自动重试 */ } }
async function loadFiles(path=currentPath.value){ currentPath.value=path;if(!currentRoot.value){files.value={items:[]};deployments.value=await request('/deployments');return}files.value=await request(`/files?rootId=${encodeURIComponent(currentRoot.value)}&path=${encodeURIComponent(path)}`);deployments.value=await request('/deployments') }
async function openItem(item:any){ if(item.isDirectory){await loadFiles(item.path);return} await downloadItem(item) }
async function downloadItem(item:any){await execute(async()=>{const response=await fetch(`/api/files/download?rootId=${encodeURIComponent(currentRoot.value)}&path=${encodeURIComponent(item.path)}`,{headers:{Authorization:`Bearer ${token.get()}`}});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message||'下载失败')}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=item.isDirectory?`${item.name}.zip`:item.name;a.click();URL.revokeObjectURL(url)})}
async function deploy(){ if(!selectedFile.value) return; await execute(async()=>{ const fd=new FormData();fd.append('file',selectedFile.value!); const path=currentPath.value ? `${currentPath.value}/${selectedFile.value!.name}` : selectedFile.value!.name; const r=await post(`/files/deploy?rootId=${encodeURIComponent(currentRoot.value)}&path=${encodeURIComponent(selectedFile.value!.name.endsWith('.zip')?currentPath.value:path)}`,fd); let message='发布完成';if(r.canRestart&&confirm(`发布完成，是否立即重启 ${r.relatedService}？`)){await post(`/services/${encodeURIComponent(r.relatedService)}/action`,{action:'restart'});message=`发布完成，${r.relatedService} 已重启`}flash(message); selectedFile.value=null; await loadFiles() }) }
async function deleteFile(createBackup:boolean){const target=deleteTarget.value;if(!target)return;await execute(async()=>{await post('/files/delete',{rootId:currentRoot.value,path:target.path,backup:createBackup});deleteTarget.value=null;flash(createBackup?'已备份并删除，可在右侧还原':'已直接删除');await loadFiles()})}
function openReplace(item:any){replaceTarget.value=item;replacementFile.value=null}
async function replaceFile(){const target=replaceTarget.value;if(!target||!replacementFile.value)return;await execute(async()=>{const fd=new FormData();fd.append('file',replacementFile.value!);const r=await post(`/files/replace?rootId=${encodeURIComponent(currentRoot.value)}&path=${encodeURIComponent(target.path)}`,fd);replaceTarget.value=null;replacementFile.value=null;let message='替换完成，原内容已备份';if(r.canRestart&&confirm(`替换完成，是否立即重启 ${r.relatedService}？`)){await post(`/services/${encodeURIComponent(r.relatedService)}/action`,{action:'restart'});message=`替换完成，${r.relatedService} 已重启`}flash(message);await loadFiles()})}
async function rollback(deployment:any){const restoring=deployment.operation==='Delete';if(!confirm(restoring?'确认还原这个文件或文件夹？当前位置的同名内容将被替换。':'确认回滚这次发布？当前文件将被替换。'))return;await execute(async()=>{await post(`/deployments/${deployment.id}/rollback`);flash(restoring?'还原完成':'回滚完成');await loadFiles()})}
async function searchLogs(){ await execute(async()=>{results.value=await post('/logs/search',{...logForm,start:new Date(logForm.start),end:new Date(logForm.end)})}) }
async function openLogContext(result:any){await execute(async()=>{logContext.value=await request(`/logs/context?rootId=${encodeURIComponent(logForm.rootId)}&file=${encodeURIComponent(result.file)}&line=${result.line}&radius=100`)})}
async function downloadLog(result:any){await execute(async()=>{const response=await fetch(`/api/logs/download?rootId=${encodeURIComponent(logForm.rootId)}&file=${encodeURIComponent(result.file)}`,{headers:{Authorization:`Bearer ${token.get()}`}});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message||'日志文件下载失败')}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=result.file.split(/[\\/]/).pop()||'application.log';a.click();URL.revokeObjectURL(url)})}
async function serviceAction(name:string,action:string){ if(!confirm(`确认${action==='stop'?'停止':action==='start'?'启动':'重启'} ${name}？`))return; await execute(async()=>{await post(`/services/${encodeURIComponent(name)}/action`,{action});flash('服务操作成功');services.value=await request('/services')}) }
async function killProcess(p:any,force=false){ if(!confirm(`确认${force?'强制':''}终止进程 ${p.pid} / ${p.name}？`))return;await execute(async()=>{await post(`/processes/${p.pid}/terminate?force=${force}`);flash('终止信号已发送');processes.value=await request('/processes')})}
async function queryJournal(){await execute(async()=>{journal.value=await post('/journal/query',{...journalForm,start:new Date(journalForm.start),end:new Date(journalForm.end)})})}
function switchLogTab(tab:'files'|'journal'){if(tab==='files'&&following.value){journalAbort?.abort();following.value=false}logTab.value=tab}
async function scrollJournalToLatest(){await nextTick();if(journalElement.value)journalElement.value.scrollTop=journalElement.value.scrollHeight}
async function toggleFollow(){
  if(following.value){journalAbort?.abort();following.value=false;return}
  if(!journalForm.service)return
  journalAbort=new AbortController();following.value=true;journal.value=[]
  try{
    const r=await fetch(`/api/journal/follow?service=${encodeURIComponent(journalForm.service)}`,{headers:{Authorization:`Bearer ${token.get()}`},signal:journalAbort.signal})
    if(!r.ok)throw new Error('实时日志连接失败')
    const reader=r.body!.getReader();const decoder=new TextDecoder();let buffer=''
    while(true){
      const {done,value}=await reader.read();if(done)break
      buffer+=decoder.decode(value,{stream:true});const blocks=buffer.split('\n\n');buffer=blocks.pop()||'';let appended=false
      for(const block of blocks){const raw=block.split('\n').find(x=>x.startsWith('data: '))?.slice(6);if(!raw)continue;try{const x=JSON.parse(raw);journal.value.push({timestamp:x.__REALTIME_TIMESTAMP?new Date(Number(x.__REALTIME_TIMESTAMP)/1000):new Date(),priority:x.PRIORITY||'',message:x.MESSAGE||x.message||''});if(journal.value.length>5000)journal.value.shift();appended=true}catch{}}
      if(appended&&following.value)await scrollJournalToLatest()
    }
  }catch(e:any){if(e.name!=='AbortError')error.value=e.message}finally{following.value=false}
}
function downloadJournal(){const text=journal.value.map(x=>`${fmtTime(x.timestamp)} [P${x.priority}] ${x.message}`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${journalForm.service||'journal'}-${Date.now()}.log`;a.click();URL.revokeObjectURL(url)}
async function loadConfigFiles(clearEditor=true){if(clearEditor)Object.assign(configEdit,{path:'',content:'',version:''});configFiles.value=configEdit.rootId?await request(`/configs/files?rootId=${encodeURIComponent(configEdit.rootId)}`):[]}
async function openConfigPage(){if(!configRoots.value.some((x:any)=>x.id===configEdit.rootId))configEdit.rootId=configRoots.value[0]?.id||'';await loadConfigFiles(true)}
async function changeConfigRoot(){await execute(async()=>loadConfigFiles(true))}
async function refreshConfigFiles(){await execute(async()=>loadConfigFiles(false))}
async function readConfig(){if(!configEdit.rootId||!configEdit.path){error.value='请选择或输入配置文件路径';return}await execute(async()=>{const r=await request(`/configs/content?rootId=${encodeURIComponent(configEdit.rootId)}&path=${encodeURIComponent(configEdit.path)}`);configEdit.content=r.content;configEdit.version=r.version})}
async function saveConfig(){if(!configEdit.version)return;if(!confirm(`确认直接保存 ${configEdit.path}？原文件会自动备份。`))return;await execute(async()=>{const r=await post('/configs/save',configEdit);configEdit.version=r.version;let message='配置已保存';if(r.canRestart&&confirm(`配置已保存，是否立即重启 ${r.relatedService}？`)){await post(`/services/${encodeURIComponent(r.relatedService)}/action`,{action:'restart'});message=`配置已保存，${r.relatedService} 已重启`}flash(message)})}
async function createUser(e:Event){const form=e.target as HTMLFormElement;const data=Object.fromEntries(new FormData(form));await execute(async()=>{await post('/users',data);flash('用户已创建');form.reset();users.value=await request('/users');userModal.value=''})}
async function changePassword(e:Event){const form=e.target as HTMLFormElement;const data=Object.fromEntries(new FormData(form));await execute(async()=>{await post('/auth/password',data);flash('密码已修改');form.reset();userModal.value=''})}
async function reloadResources(){resources.value=await request('/resources');if(!resources.value.directories.some((x:any)=>x.id===currentRoot.value))currentRoot.value=resources.value.directories[0]?.id||''}
function editDirectory(item:any){Object.assign(directoryForm,{id:item.id,name:item.name,path:item.path,canUpload:item.canUpload,relatedService:item.relatedService||'',backupExcludes:item.backupExcludes||''})}
function clearDirectory(){Object.assign(directoryForm,{id:'',name:'',path:'',canUpload:false,relatedService:'',backupExcludes:''})}
async function saveDirectory(){await execute(async()=>{await request(`/settings/directories/${encodeURIComponent(directoryForm.id)}`,{method:'PUT',body:JSON.stringify(directoryForm)});await reloadResources();flash('管理目录已保存');clearDirectory()})}
async function deleteDirectory(id:string){if(!confirm(`确认删除管理目录 ${id}？这不会删除磁盘上的真实文件。`))return;await execute(async()=>{await request(`/settings/directories/${encodeURIComponent(id)}`,{method:'DELETE'});await reloadResources();flash('管理目录已删除')})}
async function refreshServices(){await reloadResources();services.value=await request('/services');journalForm.service=resources.value.services.includes(journalForm.service)?journalForm.service:(resources.value.services[0]||'')}
function openServiceModal(){serviceCreateMode.value='existing';serviceName.value='';Object.assign(servicePublishForm,{serviceName:'',runDirectory:'',mainProgram:'',backupExcludes:'logs;files;download'});servicePackage.value=null;serviceModal.value=true}
async function saveService(){await execute(async()=>{await request(`/settings/services/${encodeURIComponent(serviceName.value)}`,{method:'PUT',body:JSON.stringify({name:serviceName.value})});await refreshServices();flash('已有服务已加入管理');serviceName.value='';serviceModal.value=false})}
async function deleteService(name:string){if(!confirm(`确认将 ${name} 移出 OSManager 管理？服务本身不会停止或卸载。`))return;await execute(async()=>{await request(`/settings/services/${encodeURIComponent(name)}`,{method:'DELETE'});await refreshServices();flash('服务已移出管理')})}
function chooseServicePackage(e:Event){servicePackage.value=(e.target as HTMLInputElement).files?.[0]||null}
async function publishService(){
  const file=servicePackage.value
  if(!file){error.value='请选择 ZIP 安装包';return}
  if(!file.name.toLowerCase().endsWith('.zip')){error.value='服务安装包必须是 ZIP 文件';return}
  if(file.size>500*1024*1024){error.value='ZIP 安装包不能超过 500MB';return}
  if(!confirm(`确认发布并安装 ${servicePublishForm.serviceName}？这会写入运行目录、创建 systemd unit 并启动服务。`))return
  await execute(async()=>{const fd=new FormData();fd.append('file',file);const query=new URLSearchParams(servicePublishForm).toString();await post(`/services/publish?${query}`,fd);await refreshServices();flash(`${servicePublishForm.serviceName} 已发布并启动`);Object.assign(servicePublishForm,{serviceName:'',runDirectory:'',mainProgram:'',backupExcludes:'logs;files;download'});servicePackage.value=null;serviceModal.value=false})
}
function editLogSource(item:any){Object.assign(logSourceForm,{id:item.id,name:item.name,path:item.path,filePattern:item.filePattern})}
function clearLogSource(){Object.assign(logSourceForm,{id:'',name:'',path:'',filePattern:'*.log;*.txt'})}
async function saveLogSource(){await execute(async()=>{await request(`/settings/logs/${encodeURIComponent(logSourceForm.id)}`,{method:'PUT',body:JSON.stringify(logSourceForm)});await reloadResources();logForm.rootId||=logSourceForm.id;flash('日志源已保存');clearLogSource()})}
async function deleteLogSource(id:string){if(!confirm(`确认删除日志源 ${id}？`))return;await execute(async()=>{await request(`/settings/logs/${encodeURIComponent(id)}`,{method:'DELETE'});await reloadResources();if(logForm.rootId===id)logForm.rootId=resources.value.logs?.[0]?.id||'';flash('日志源已删除')})}
function openUserModal(type:string,user:any=null){selectedUser.value=user;userModal.value=type;if(user)Object.assign(userEdit,{displayName:user.display_name,role:user.role,isEnabled:Boolean(user.is_enabled)})}
async function updateUser(){await execute(async()=>{await request(`/users/${selectedUser.value.id}`,{method:'PUT',body:JSON.stringify(userEdit)});users.value=await request('/users');flash('用户已更新');userModal.value=''})}
async function resetUserPassword(e:Event){const form=e.target as HTMLFormElement;const password=String(new FormData(form).get('newPassword')||'');await execute(async()=>{await post(`/users/${selectedUser.value.id}/password`,{newPassword:password});flash('密码已重置');form.reset();userModal.value=''})}
async function toggleUser(user:any){await execute(async()=>{await request(`/users/${user.id}`,{method:'PUT',body:JSON.stringify({displayName:user.display_name,role:user.role,isEnabled:!Boolean(user.is_enabled)})});users.value=await request('/users');flash(user.is_enabled?'用户已禁用':'用户已启用')})}
onMounted(()=>{if(token.get())boot().catch(()=>signOut())});onUnmounted(()=>{if(timer)clearInterval(timer);journalAbort?.abort()})
</script>

<template>
  <div v-if="!currentUser" class="login-shell">
    <div class="login-grid"></div><section class="login-card">
      <div class="brand-mark">OS<span>/</span>M</div><p class="eyebrow">LOCAL HOST CONTROL</p>
      <h1>主机在手，<br><em>边界清晰。</em></h1><p class="muted">面向 Linux 主机的受限运维控制台</p>
      <form @submit.prevent="signIn" class="login-form"><label>账户<input v-model="login.userName" autocomplete="username"></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password"></label><button class="primary" :disabled="busy">{{busy?'正在验证…':'进入控制台 →'}}</button></form>
      <p v-if="error" class="error">{{error}}</p><p class="login-foot">首次登录后请立即修改默认密码</p>
    </section>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="logo"><b>OS<span>/</span>M</b><small>HOST CONTROL</small></div><nav><button v-for="m in visibleMenu" :key="m[0]" :class="{active:view===m[0]}" @click="load(m[0])"><i>{{m[1]}}</i>{{m[2]}}</button></nav><div class="sidebar-foot"><span class="pulse"></span><div><b>{{resources.platform==='linux'?'主机在线':'开发模式'}}</b><small>{{resources.demoMode?'命令不会执行':'受限操作已启用'}}</small></div></div></aside>
    <main><header><div><p class="eyebrow">OSMANAGER / {{view.toUpperCase()}}</p><h2>{{title}}</h2></div><div class="operator"><span>{{currentUser.displayName}}</span><small>{{currentUser.role}}</small><button @click="signOut">退出</button></div></header>
      <div v-if="error" class="toast error">{{error}}<button @click="error=''">×</button></div><div v-if="notice" class="toast success">{{notice}}</div><div v-if="busy" class="progress"></div>
      <section v-if="view==='dashboard'" class="page dashboard">
        <div class="hero panel"><div><p class="eyebrow">NODE / {{dashboard.host}}</p><h3>系统运行平稳</h3><p>{{dashboard.os}}</p></div><div class="hero-stat"><small>UPTIME</small><strong>{{Math.floor((dashboard.uptimeSeconds||0)/3600)}}<i>h</i></strong></div></div>
        <div class="metric-grid"><article class="metric panel"><div><span>CPU 使用率</span><strong>{{dashboard.metrics.at(-1)?.cpu?.toFixed(1)||'0.0'}}<i>%</i></strong></div><MetricChart :points="dashboard.metrics" field="cpu" color="#1f883d"/></article><article class="metric panel"><div><span>内存使用率</span><strong>{{dashboard.metrics.at(-1)?.memory?.toFixed(1)||'0.0'}}<i>%</i></strong></div><MetricChart :points="dashboard.metrics" field="memory" color="#0969da"/></article></div>
        <div class="panel table-panel"><div class="panel-title"><h3>受管服务</h3><span>点击服务进入管理 · {{dashboard.services.length}} SERVICES</span></div><table><thead><tr><th>服务</th><th>加载状态</th><th>运行状态</th><th>主进程</th><th>启动时间</th></tr></thead><tbody><tr v-for="s in dashboard.services" class="clickable service-link" title="进入服务管理" @click="load('services')"><td class="mono"><b>{{s.service}}</b> <span>→</span></td><td><span class="badge" :class="s.loadState==='loaded'?'ok':'bad'">{{s.loadState}}</span></td><td><span class="badge" :class="s.activeState==='active'?'ok':'warn'">{{s.activeState}}</span></td><td>{{s.mainPid}}</td><td>{{s.since||'—'}}</td></tr><tr v-if="!dashboard.services.length"><td colspan="5" class="empty">尚未配置受管服务</td></tr></tbody></table></div>
      </section>
      <section v-else-if="view==='files'" class="page"><div v-if="!resources.directories.length" class="settings-note">尚未配置管理目录，请由管理员先到“资源设置”新增目录，或在“服务管理”中安装服务。</div><div class="toolbar panel"><select v-model="currentRoot" @change="loadFiles('')"><option value="" disabled>请选择管理目录</option><option v-for="r in resources.directories" :value="r.id">{{r.name}}</option></select><span class="path">/{{currentPath}}</span><label class="file-pick"><input type="file" :disabled="!currentRoot" @change="selectedFile=($event.target as HTMLInputElement).files?.[0]||null">{{selectedFile?.name||'选择文件或 ZIP'}}</label><button class="primary small" :disabled="!selectedFile||!currentRoot" @click="deploy">发布</button></div><div class="split"><div class="panel table-panel"><div class="panel-title"><h3>文件</h3><button v-if="currentPath" class="ghost" @click="loadFiles(currentPath.split('/').slice(0,-1).join('/'))">↑ 返回上级</button></div><table><thead><tr><th>名称</th><th>大小</th><th>修改时间</th><th class="file-action-heading">操作</th></tr></thead><tbody><tr v-for="f in files.items" :key="f.path" @dblclick="openItem(f)" class="clickable"><td><b>{{f.isDirectory?'▰':'▤'}} {{f.name}}</b></td><td>{{f.isDirectory?'—':fmtBytes(f.size)}}</td><td>{{fmtTime(f.modified)}}</td><td class="file-actions"><div class="row-actions"><button type="button" class="action-button download" title="下载" @click.stop="downloadItem(f)" @dblclick.stop><span>↓</span>下载</button><button type="button" class="action-button replace" title="替换" @click.stop="openReplace(f)" @dblclick.stop><span>↻</span>替换</button><button type="button" class="action-button delete" title="删除" @click.stop="deleteTarget=f" @dblclick.stop><span>×</span>删除</button></div></td></tr><tr v-if="!files.items.length"><td colspan="4" class="empty">{{currentRoot?'目录为空':'尚未选择管理目录'}}</td></tr></tbody></table></div><div class="panel table-panel"><div class="panel-title"><h3>变更与备份</h3></div><div v-for="d in deployments" :key="d.id" class="deploy-row"><div><b>#{{d.id}} · {{d.relative_path}}</b><small>{{d.operation==='Delete'?'删除备份':d.operation==='Replace'?'内容替换':'文件发布'}} · {{d.user_name}} · {{fmtTime(d.created_at)}}</small></div><span class="badge" :class="d.status==='Succeeded'?'ok':'warn'">{{d.status}}</span><button v-if="d.status==='Succeeded'" class="history-action" :class="d.operation==='Delete'?'restore':'rollback'" @click="rollback(d)"><span>{{d.operation==='Delete'?'↥':'↶'}}</span>{{d.operation==='Delete'?'还原':'回滚'}}</button></div><p v-if="!deployments.length" class="empty">暂无变更记录</p></div></div></section>
      <section v-else-if="view==='logs'" class="page"><div class="log-tabs" role="tablist" aria-label="日志类型"><button role="tab" :aria-selected="logTab==='files'" :class="{active:logTab==='files'}" @click="switchLogTab('files')">文件日志</button><button role="tab" :aria-selected="logTab==='journal'" :class="{active:logTab==='journal'}" @click="switchLogTab('journal')">Journal 日志</button></div><template v-if="logTab==='files'"><div v-if="!resources.logs?.length" class="settings-note">尚未配置日志源，请由管理员先到“资源设置”添加日志目录或日志文件。</div><div class="panel query log-query" :class="{collapsed:!logQueryOpen}"><div class="panel-title"><h3>普通文件日志</h3><div class="actions"><span>支持 .LOG / .TXT · MAX 7 DAYS</span><button type="button" class="ghost collapse-toggle" :aria-expanded="logQueryOpen" @click="logQueryOpen=!logQueryOpen">{{logQueryOpen?'收起条件':'展开条件'}} <i>{{logQueryOpen?'⌃':'⌄'}}</i></button></div></div><div v-show="logQueryOpen" class="form-grid"><label>日志源<select v-model="logForm.rootId"><option value="" disabled>请选择日志源</option><option v-for="r in resources.logs" :value="r.id">{{r.name}} · {{r.path}}</option></select></label><label>开始时间<input v-model="logForm.start" type="datetime-local"></label><label>结束时间<input v-model="logForm.end" type="datetime-local"></label><label class="wide">搜索内容<input v-model="logForm.query" placeholder="留空显示时间范围内的全部内容"></label><button class="primary" :disabled="!logForm.rootId" @click="searchLogs">开始搜索</button></div></div><div class="panel log-output" :class="{'query-collapsed':!logQueryOpen}"><div class="panel-title"><h3>匹配结果</h3><span>{{results.length}} MATCHES</span></div><div v-for="r in results" class="log-line log-result"><span>{{r.file}}:{{r.line}}</span><code>{{r.content}}</code><div class="actions"><button @click="openLogContext(r)">查看上下文</button><button @click="downloadLog(r)">下载文件</button></div></div><p v-if="!results.length" class="empty">等待搜索条件</p></div></template><div v-else class="panel query journal-panel log-query" :class="{collapsed:!journalQueryOpen}"><div class="panel-title"><h3>Journal 日志</h3><div class="actions"><span v-if="following" class="live">● LIVE</span><button v-if="journal.length" class="ghost" @click="downloadJournal">下载日志</button><button type="button" class="ghost collapse-toggle" :aria-expanded="journalQueryOpen" @click="journalQueryOpen=!journalQueryOpen">{{journalQueryOpen?'收起条件':'展开条件'}} <i>{{journalQueryOpen?'⌃':'⌄'}}</i></button></div></div><div v-show="journalQueryOpen" class="form-grid"><label>服务<select v-model="journalForm.service"><option v-for="s in resources.services">{{s}}</option></select></label><label>开始<input v-model="journalForm.start" type="datetime-local"></label><label>结束<input v-model="journalForm.end" type="datetime-local"></label><label>关键词<input v-model="journalForm.query"></label><button class="primary" @click="queryJournal">历史查询</button><button class="ghost" @click="toggleFollow">{{following?'停止实时':'实时滚动'}}</button></div><div ref="journalElement" class="journal" :class="{'query-collapsed':!journalQueryOpen}"><div v-for="j in journal" class="log-line"><span>{{fmtTime(j.timestamp)}} · P{{j.priority}}</span><code>{{j.message}}</code></div></div></div></section>
      <section v-else-if="view==='services'" class="page services-page">
        <div class="services-heading"><div><h3>受管服务</h3><p>这里的服务才允许执行启动、停止、重启和 Journal 日志操作。</p></div><span>{{services.length}} SERVICES</span></div>
        <div class="service-grid"><article v-for="s in services" class="panel service-card"><div><span class="service-icon">◉</span><span class="badge" :class="s.loadState==='loaded'?(s.activeState==='active'?'ok':'warn'):'bad'">{{s.loadState==='loaded'?s.activeState:'未安装'}}</span></div><h3>{{s.service}}</h3><p v-if="s.loadState==='loaded'">PID {{s.mainPid}} · {{s.subState}}</p><p v-else class="service-error">systemd 未加载此服务，请检查 unit 文件并执行 daemon-reload</p><div class="actions"><button :disabled="s.loadState!=='loaded'" @click="serviceAction(s.service,'start')">启动</button><button :disabled="s.loadState!=='loaded'" @click="serviceAction(s.service,'restart')">重启</button><button :disabled="s.loadState!=='loaded'" class="danger-text" @click="serviceAction(s.service,'stop')">停止</button><button v-if="currentUser.role==='Admin'" class="remove-service" @click="deleteService(s.service)">移出管理</button></div></article><button v-if="currentUser.role==='Admin'" type="button" class="panel service-add-card" aria-label="添加服务" @click="openServiceModal"><span>＋</span><b>添加服务</b><small>已有 systemd 服务或 ZIP 安装包</small></button><div v-else-if="!services.length" class="panel empty big">尚未添加受管服务。</div></div>
      </section>
      <section v-else-if="view==='processes'" class="page panel table-panel process-page"><div class="panel-title"><div><h3>进程快照</h3><small>显示 {{filteredProcesses.length}} / {{processes.length}} 个进程</small></div><div class="process-tools"><input v-model.trim="processFilter" type="search" placeholder="输入进程名称或 PID" aria-label="筛选进程"><button class="ghost" @click="load('processes')">刷新</button></div></div><table><thead><tr><th>PID</th><th>进程</th><th>内存</th><th>CPU 时间</th><th>启动时间</th><th></th></tr></thead><tbody><tr v-for="p in filteredProcesses" :key="p.pid"><td class="mono">{{p.pid}}</td><td><b>{{p.name}}</b></td><td>{{fmtBytes(p.memory)}}</td><td>{{p.cpu.toFixed(1)}}s</td><td>{{p.started?fmtTime(p.started):'—'}}</td><td class="actions"><button class="danger-text" @click="killProcess(p)">终止</button><button class="danger-text" @click="killProcess(p,true)">强制</button></td></tr><tr v-if="!filteredProcesses.length"><td colspan="6" class="empty">没有匹配的进程</td></tr></tbody></table></section>
      <section v-else-if="view==='configs'" class="page config-page"><div v-if="!configRoots.length" class="settings-note">尚无允许编辑的管理目录，请由管理员先到“资源设置”开启目录的上传和配置编辑权限。</div><div class="config-workspace"><aside class="panel config-picker"><div class="panel-title"><div><h3>选择配置文件</h3><small>自动发现常见配置格式</small></div><span>{{configFiles.length}} FILES</span></div><label>管理目录<select v-model="configEdit.rootId" @change="changeConfigRoot"><option value="" disabled>请选择管理目录</option><option v-for="r in configRoots" :value="r.id">{{r.name}} · {{r.path}}</option></select></label><label>配置文件路径<div class="inline"><input v-model.trim="configEdit.path" list="config-file-options" placeholder="从列表选择或手动输入" @change="configFiles.includes(configEdit.path)&&readConfig()"><datalist id="config-file-options"><option v-for="file in configFiles" :value="file"></option></datalist><button type="button" :disabled="!configEdit.rootId||!configEdit.path" @click="readConfig">读取</button></div><small>扫描 .json、.ini、.config、.yaml、.yml、.conf；也可以手动输入相对路径。</small></label><button type="button" class="ghost config-refresh" :disabled="!configEdit.rootId" @click="refreshConfigFiles">↻ 重新扫描目录</button></aside><section class="panel config-editor"><div class="panel-title"><div><h3>{{configEdit.path||'配置内容'}}</h3><small>{{configEdit.version?'已读取，可直接编辑保存':'请先选择并读取配置文件'}}</small></div><span>{{configEdit.version?'EDITING':'NO FILE'}}</span></div><textarea v-model="configEdit.content" :disabled="!configEdit.version" spellcheck="false" placeholder="配置文件内容"></textarea><div class="config-savebar"><span>保存前自动备份，并检查文件是否被其他程序修改。</span><button v-if="currentUser.role==='Admin'||currentUser.role==='Editor'" class="primary" :disabled="!configEdit.version||busy" @click="saveConfig">保存配置</button></div></section></div></section>
      <section v-else-if="view==='audit'" class="page panel table-panel"><div class="panel-title"><h3>审计事件</h3><span>IMMUTABLE TRAIL</span></div><table><thead><tr><th>时间</th><th>操作人</th><th>动作</th><th>目标</th><th>结果</th><th>来源</th></tr></thead><tbody><tr v-for="a in audits"><td>{{fmtTime(a.created_at)}}</td><td>{{a.user_name}}</td><td class="mono">{{a.action}}</td><td>{{a.target}}</td><td><span class="badge" :class="a.success?'ok':'bad'">{{a.success?'成功':'失败'}}</span></td><td>{{a.ip}}</td></tr></tbody></table></section>
      <section v-else-if="view==='users'" class="page panel table-panel"><div class="panel-title"><h3>本地用户</h3><div class="actions"><button @click="openUserModal('selfPassword')">修改我的密码</button><button class="primary small" @click="openUserModal('add')">添加用户</button></div></div><table><thead><tr><th>用户</th><th>用户名</th><th>角色</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="u in users"><td><div class="user-cell"><span class="avatar">{{u.display_name.slice(0,1)}}</span><b>{{u.display_name}}</b></div></td><td class="mono">{{u.username}}</td><td><span class="badge">{{u.role}}</span></td><td><span class="badge" :class="u.is_enabled?'ok':'bad'">{{u.is_enabled?'已启用':'已禁用'}}</span></td><td>{{fmtTime(u.created_at)}}</td><td><div class="actions"><button @click="openUserModal('edit',u)">编辑</button><button @click="openUserModal('reset',u)">重置密码</button><button v-if="u.id!==currentUser.id" :class="u.is_enabled?'danger-text':''" @click="toggleUser(u)">{{u.is_enabled?'禁用':'启用'}}</button></div></td></tr></tbody></table></section>
      <section v-else-if="view==='settings'" class="page"><div class="settings-note">配置保存在 SQLite 中并立即生效。删除目录配置不会删除 Linux 上的真实目录或文件；systemd 服务请统一到“服务管理”中添加。</div><div class="split"><form class="panel query" @submit.prevent="saveDirectory"><div class="panel-title"><h3>{{directoryForm.id?'编辑管理目录':'新增管理目录'}}</h3><button v-if="directoryForm.id" type="button" class="ghost" @click="clearDirectory">清空</button></div><label>目录标识<input v-model.trim="directoryForm.id" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" placeholder="app-a" :readonly="resources.directories.some((x:any)=>x.id===directoryForm.id)" required><small>创建后不可修改，用于 API 和审计记录</small></label><label>显示名称<input v-model.trim="directoryForm.name" placeholder="应用 A 发布目录" required></label><label>Linux 绝对路径<input v-model.trim="directoryForm.path" placeholder="/opt/apps/app-a" required></label><label>关联服务<select v-model="directoryForm.relatedService"><option value="">不关联服务</option><option v-for="s in resources.services" :value="s">{{s}}</option></select></label><label>备份排除文件夹<input v-model.trim="directoryForm.backupExcludes" placeholder="logs;files;download"><small>相对于管理目录；使用分号分隔。ZIP 备份和回滚都保留这些目录。</small></label><label class="check-label"><input v-model="directoryForm.canUpload" type="checkbox">允许上传、ZIP 发布和配置编辑</label><button class="primary">保存管理目录</button></form><div class="panel table-panel"><div class="panel-title"><h3>管理目录</h3><span>{{resources.directories.length}} DIRECTORIES</span></div><div v-for="r in resources.directories" class="deploy-row resource-row"><div><b>{{r.name}} <span class="resource-id">{{r.id}}</span></b><small>{{r.path}} · {{r.canUpload?'允许更新':'只读'}}{{r.relatedService?` · ${r.relatedService}`:''}}</small><small v-if="r.backupExcludes" class="exclude-note">备份排除：{{r.backupExcludes}}</small></div><div class="actions"><button @click="editDirectory(r)">编辑</button><button class="danger-text" @click="deleteDirectory(r.id)">删除</button></div></div><p v-if="!resources.directories.length" class="empty">尚未配置管理目录</p></div></div></section>
      <section v-if="view==='settings'" class="page log-settings-page"><div class="split"><form class="panel query" @submit.prevent="saveLogSource"><div class="panel-title"><h3>{{logSourceForm.id?'编辑日志源':'新增日志源'}}</h3><button v-if="logSourceForm.id" type="button" class="ghost" @click="clearLogSource">清空</button></div><label>日志源标识<input v-model.trim="logSourceForm.id" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" placeholder="ihr-logs" :readonly="resources.logs?.some((x:any)=>x.id===logSourceForm.id)" required></label><label>显示名称<input v-model.trim="logSourceForm.name" placeholder="IHR 应用日志" required></label><label>日志目录或完整文件路径<input v-model.trim="logSourceForm.path" placeholder="/app/publish-v2.2/logs" required><small>可以配置独立于程序发布目录之外的任意授权路径</small></label><label>文件匹配规则<input v-model.trim="logSourceForm.filePattern" placeholder="*.log;*.txt" required><small>多个规则使用分号分隔；填写完整文件路径时忽略此项</small></label><button class="primary">保存日志源</button></form><div class="panel table-panel"><div class="panel-title"><h3>日志源</h3><span>{{resources.logs?.length||0}} LOG SOURCES</span></div><div v-for="r in resources.logs" class="deploy-row resource-row"><div><b>{{r.name}} <span class="resource-id">{{r.id}}</span></b><small>{{r.path}} · {{r.filePattern}}</small></div><div class="actions"><button @click="editLogSource(r)">编辑</button><button class="danger-text" @click="deleteLogSource(r.id)">删除</button></div></div><p v-if="!resources.logs?.length" class="empty">尚未配置日志源</p></div></div></section>
    </main>
    <div v-if="replaceTarget" class="modal-backdrop" @mousedown.self="replaceTarget=null;replacementFile=null">
      <section class="modal replace-modal" role="dialog" aria-modal="true" aria-labelledby="replace-title">
        <div class="modal-head"><div><h3 id="replace-title">替换{{replaceTarget.isDirectory?'文件夹':'文件'}}</h3><small>原内容会先完整备份，替换后可以回滚。</small></div><button type="button" aria-label="关闭" @click="replaceTarget=null;replacementFile=null">×</button></div>
        <div class="delete-target"><span>{{replaceTarget.isDirectory?'▰':'▤'}}</span><div><b>{{replaceTarget.name}}</b><small>/{{replaceTarget.path}}</small></div></div>
        <label class="replacement-picker"><input type="file" :accept="replaceTarget.isDirectory?'.zip,application/zip':undefined" @change="replacementFile=($event.target as HTMLInputElement).files?.[0]||null"><span>{{replaceTarget.isDirectory?'ZIP':'FILE'}}</span><div><b>{{replacementFile?.name||`选择新的${replaceTarget.isDirectory?' ZIP 压缩包':'文件'}`}}</b><small>{{replacementFile?fmtBytes(replacementFile.size):replaceTarget.isDirectory?'ZIP 内容将替换当前文件夹':'文件名可以与原文件不同'}}</small></div></label>
        <p class="replace-warning">{{replaceTarget.isDirectory?'当前文件夹会先完整备份，然后清空并解压 ZIP。':'当前文件会先完整备份，再写入所选文件。'}}回滚时会恢复替换前的内容。</p>
        <div class="modal-actions"><button type="button" @click="replaceTarget=null;replacementFile=null">取消</button><button type="button" class="primary" :disabled="!replacementFile||busy" @click="replaceFile">备份并替换</button></div>
      </section>
    </div>
    <div v-if="deleteTarget" class="modal-backdrop" @mousedown.self="deleteTarget=null">
      <section class="modal delete-modal" role="alertdialog" aria-modal="true" aria-labelledby="delete-title">
        <div class="modal-head"><div><h3 id="delete-title">删除{{deleteTarget.isDirectory?'文件夹':'文件'}}</h3><small>请选择是否在删除前创建可还原的备份。</small></div><button type="button" aria-label="关闭" @click="deleteTarget=null">×</button></div>
        <div class="delete-target"><span>{{deleteTarget.isDirectory?'▰':'▤'}}</span><div><b>{{deleteTarget.name}}</b><small>/{{deleteTarget.path}}</small></div></div>
        <p class="delete-warning">直接删除后无法通过 OSManager 恢复。选择“备份后删除”会完整保存所选文件或文件夹，并在右侧“变更与备份”中提供还原操作。</p>
        <div class="modal-actions"><button type="button" @click="deleteTarget=null">取消</button><button type="button" class="danger" :disabled="busy" @click="deleteFile(false)">直接删除</button><button type="button" class="primary" :disabled="busy" @click="deleteFile(true)">备份后删除</button></div>
      </section>
    </div>
    <div v-if="serviceModal" class="modal-backdrop" @mousedown.self="serviceModal=false">
      <section class="modal service-modal">
        <div class="modal-head"><div><h3>添加服务</h3><small>接管已有 systemd 服务，或上传应用安装包创建新服务。</small></div><button type="button" aria-label="关闭" @click="serviceModal=false">×</button></div>
        <div class="service-mode-tabs" role="tablist" aria-label="新增服务方式"><button type="button" role="tab" :aria-selected="serviceCreateMode==='existing'" :class="{active:serviceCreateMode==='existing'}" @click="serviceCreateMode='existing'">添加已有服务</button><button type="button" role="tab" :aria-selected="serviceCreateMode==='package'" :class="{active:serviceCreateMode==='package'}" @click="serviceCreateMode='package'">上传 ZIP 安装服务</button></div>
        <form v-if="serviceCreateMode==='existing'" class="service-existing-form" @submit.prevent="saveService"><label>systemd 服务名称<input v-model.trim="serviceName" pattern="[A-Za-z0-9_.@:-]+\.service" placeholder="ihr.service" required><small>服务必须已经安装并能被 systemd 加载；保存后会加入控制白名单。</small></label><div class="modal-actions"><button type="button" @click="serviceModal=false">取消</button><button class="primary" :disabled="busy">加入管理</button></div></form>
        <form v-else class="service-publish-form" @submit.prevent="publishService"><div class="publish-fields"><label>systemd 服务名称<input v-model.trim="servicePublishForm.serviceName" pattern="[A-Za-z0-9_.@:-]+\.service" placeholder="ihr.service" required></label><label>Linux 运行目录<input v-model.trim="servicePublishForm.runDirectory" placeholder="/app/publish-v2.2" required></label><label>主程序相对路径<input v-model.trim="servicePublishForm.mainProgram" placeholder="IHR.Api.dll" required><small>支持 .NET DLL 或原生可执行文件，可填写子目录路径。</small></label><label>备份排除文件夹<input v-model.trim="servicePublishForm.backupExcludes" placeholder="logs;files;download"><small>以分号分隔；后续发布和回滚都会保留这些目录。</small></label></div><label class="package-picker"><input type="file" accept=".zip,application/zip" @change="chooseServicePackage"><span>ZIP</span><div><b>{{servicePackage?.name||'选择应用程序安装包'}}</b><small>{{servicePackage?fmtBytes(servicePackage.size):'仅支持 ZIP，最大 500MB'}}</small></div></label><p class="publish-warning">发布会先备份运行目录，再解压安装包、生成受限 systemd unit，并立即启用和启动服务。</p><div class="modal-actions"><button type="button" @click="serviceModal=false">取消</button><button class="primary" :disabled="!servicePackage||busy">发布并安装服务</button></div></form>
      </section>
    </div>
    <div v-if="userModal" class="modal-backdrop" @mousedown.self="userModal=''">
      <form v-if="userModal==='add'" class="modal" @submit.prevent="createUser"><div class="modal-head"><h3>添加本地用户</h3><button type="button" @click="userModal=''">×</button></div><label>用户名<input name="userName" autocomplete="off" required></label><label>显示名称<input name="displayName" required></label><label>初始密码<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><label>角色<select name="role"><option>Viewer</option><option>Editor</option><option>Approver</option><option>Operator</option><option>Admin</option></select></label><div class="modal-actions"><button type="button" @click="userModal=''">取消</button><button class="primary">创建用户</button></div></form>
      <form v-else-if="userModal==='selfPassword'" class="modal" @submit.prevent="changePassword"><div class="modal-head"><h3>修改我的密码</h3><button type="button" @click="userModal=''">×</button></div><label>当前密码<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label><div class="modal-actions"><button type="button" @click="userModal=''">取消</button><button class="primary">更新密码</button></div></form>
      <form v-else-if="userModal==='reset'" class="modal" @submit.prevent="resetUserPassword"><div class="modal-head"><h3>重置 {{selectedUser?.display_name}} 的密码</h3><button type="button" @click="userModal=''">×</button></div><label>新密码<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label><p class="modal-help">密码至少 10 个字符。保存后请通过安全渠道通知用户。</p><div class="modal-actions"><button type="button" @click="userModal=''">取消</button><button class="primary">重置密码</button></div></form>
      <form v-else-if="userModal==='edit'" class="modal" @submit.prevent="updateUser"><div class="modal-head"><h3>编辑用户 {{selectedUser?.username}}</h3><button type="button" @click="userModal=''">×</button></div><label>显示名称<input v-model.trim="userEdit.displayName" required></label><label>角色<select v-model="userEdit.role"><option>Viewer</option><option>Editor</option><option>Approver</option><option>Operator</option><option>Admin</option></select></label><label class="check-label"><input v-model="userEdit.isEnabled" type="checkbox">允许此用户登录</label><div class="modal-actions"><button type="button" @click="userModal=''">取消</button><button class="primary">保存修改</button></div></form>
    </div>
    <div v-if="logContext" class="modal-backdrop" @mousedown.self="logContext=null">
      <section class="modal log-context-modal"><div class="modal-head"><div><h3>{{logContext.file}}</h3><small>命中第 {{logContext.targetLine}} 行 · 前后各 100 行</small></div><button type="button" @click="logContext=null">×</button></div><div class="context-lines"><div v-for="line in logContext.lines" :class="{hit:line.matched}"><span>{{line.number}}</span><code>{{line.content||' '}}</code></div></div><div class="modal-actions"><span>显示 {{logContext.startLine}}–{{logContext.endLine}} 行</span><button type="button" @click="logContext=null">关闭</button></div></section>
    </div>
  </div>
</template>
